sys_script_include.script:
var UserInfoUtils = Class.create();
UserInfoUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUserInformationUtilsByID: function() {
        var user_object = {};
        var userId = this.getParameter('sysparm_sys_id');
        //gs.log(usr,'test');

        var gr = new GlideRecord('sys_user');
        gr.addQuery('sys_id', userId);
        gr.query();
        if (gr.next()) {
            user_object['name'] = gr.getValue('name');
            user_object['comp'] = gr.getValue('company');
            user_object['dept'] = gr.getValue('department');
            user_object['manager'] = gr.getValue('manager');
            user_object['funct'] = gr.getValue('title');
            user_object['email'] = gr.getValue('email');
            user_object['phone'] = gr.getValue('phone');
            user_object['activity_rate'] = gr.getValue('u_activity_rate');
            user_object['contract_type'] = gr.getValue('u_contract_type');
			user_object['commitment_date'] = gr.getValue('u_commitment_date');
            user_object['first_name'] = gr.getValue('first_name');
            user_object['last_name'] = gr.getValue('last_name');
            user_object['city'] = gr.getValue('city');
            user_object['zip'] = gr.getValue('zip');
            user_object['street'] = gr.getValue('street');
            user_object['country'] = gr.getValue('country');
            user_object['home_city'] = gr.getValue('u_home_city');
            user_object['home_zip'] = gr.getValue('u_home_zip');
            user_object['home_street'] = gr.getValue('u_home_street');
        }

        return JSON.stringify(user_object);
    },

    type: 'UserInfoUtils'
});
